1	import fs from 'node:fs';
2	import path from 'node:path';
3	import { spawnSync } from 'node:child_process';
4	import crypto from 'node:crypto';
5	import { fileURLToPath } from 'node:url';
6	import { RUNTIME_FILES } from '../../lib/tool-build.mjs';
7	const base = path.dirname(fileURLToPath(import.meta.url));
8	const [label, exe, ...args] = process.argv.slice(2);
9	if (!/^[a-z][a-z0-9-]*$/.test(label ?? '') || !exe) throw Error('unique-label exe args');
10	const dir = path.join(base, 'commands', label); fs.mkdirSync(dir, { recursive: true });
11	if (fs.existsSync(path.join(dir, 'result.json'))) throw Error('Never overwrite evidence');
12	const sha = x => crypto.createHash('sha256').update(x).digest('hex');
13	function buildObservation() {
14	  if (!/bin[\\/]ai-writer\.mjs$/.test(args[0] ?? '')) return null;
15	  const root = path.dirname(path.dirname(path.resolve(args[0]))), pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'))), v = pkg.version;
16	  const refs = v.startsWith('0.1.') ? RUNTIME_FILES.slice(0, 3) : v.startsWith('0.2.') ? RUNTIME_FILES.slice(0, 5) : v.startsWith('0.3.') ? RUNTIME_FILES.slice(0, 7) : v.startsWith('0.4.') ? RUNTIME_FILES.slice(0, 9) : v.startsWith('0.5.') ? RUNTIME_FILES.slice(0, 11) : v.startsWith('0.6.') ? RUNTIME_FILES.slice(0, 12) : RUNTIME_FILES;
17	  const rows = refs.map(ref => [ref, sha(fs.readFileSync(path.join(root, ref)))]);
18	  return { root, version: v, runtime_guard_id: sha(JSON.stringify(rows)), basis: 'disk bytes observed around a fresh CLI process; not module-byte attestation' };
19	}
20	let input = null; const at = args.indexOf('--input');
21	if (at >= 0) { const file = path.resolve(args[at + 1]); const bytes = fs.readFileSync(file); fs.writeFileSync(path.join(dir, 'input.raw.json'), bytes, { flag: 'wx' }); input = { file, sha256: sha(bytes) }; }
22	const projectAt = args.indexOf('--project'), stateFile = projectAt < 0 ? null : path.resolve(args[projectAt + 1], '.writer/state.json');
23	function snap(name) { if (!stateFile || !fs.existsSync(stateFile)) return null; const bytes = fs.readFileSync(stateFile); fs.writeFileSync(path.join(dir, name), bytes, { flag: 'wx' }); return sha(bytes); }
24	const before = snap('before-state.json'), build_before = buildObservation(), start = Date.now();
25	if (exe === 'npm.cmd' && args.some(x => !/^[A-Za-z0-9:_-]+$/.test(x))) throw Error('Unsafe npm arguments');
26	const actualExe = exe === 'npm.cmd' ? process.env.ComSpec : exe;
27	const actualArgs = exe === 'npm.cmd' ? ['/d', '/c', 'npm.cmd', ...args] : args;
28	const result = spawnSync(actualExe, actualArgs, { windowsHide: true, timeout: 1200000, maxBuffer: 64 * 1024 * 1024 });
29	fs.writeFileSync(path.join(dir, 'stdout.raw.txt'), result.stdout ?? Buffer.alloc(0));
30	fs.writeFileSync(path.join(dir, 'stderr.raw.txt'), result.stderr ?? Buffer.alloc(0));
31	const meta = { exe, args, cwd: process.cwd(), started_at: new Date(start).toISOString(), elapsed_ms: Date.now() - start, exit_code: result.status, signal: result.signal, error: result.error?.message, input, before_state_sha256: before, after_state_sha256: snap('after-state.json') };
32	meta.build_before = build_before; meta.build_after = buildObservation(); meta.runtime_files_stable = build_before === null ? null : meta.build_after.runtime_guard_id === build_before.runtime_guard_id;
33	fs.writeFileSync(path.join(dir, 'result.json'), JSON.stringify(meta, null, 2) + '\n', { flag: 'wx' });
34	console.log(JSON.stringify(meta)); process.exitCode = result.status ?? 1;
